mapper.insert:
INSERT INTO mt_async_task (
    task_type, biz_key, scope_key, payload_json, status, retry_count, max_retry_count,
    available_at, claimed_at, finished_at, worker_id, last_error, create_time, update_time
) VALUES (
    #{taskType}, #{bizKey}, #{scopeKey}, #{payloadJson}, #{status}, #{retryCount}, #{maxRetryCount},
    #{availableAt}, #{claimedAt}, #{finishedAt}, #{workerId}, #{lastError}, #{createTime}, #{updateTime}
)

mapper.select:
SELECT 
FROM mt_async_task
WHERE task_type = #{taskType}
  AND biz_key = #{bizKey}
LIMIT 1

SELECT id
FROM mt_async_task
WHERE task_type = #{taskType}
  AND status = 'PENDING'
  AND available_at <= #{availableAt}
ORDER BY available_at ASC, id ASC
LIMIT #{limit}

mapper.update:
UPDATE mt_async_task
SET status = 'PROCESSING',
    worker_id = #{workerId},
    claimed_at = #{claimedAt},
    finished_at = NULL,
    update_time = #{claimedAt}
WHERE id = #{id}
  AND task_type = #{taskType}
  AND status = 'PENDING'

UPDATE mt_async_task
SET status = 'SUCCESS',
    finished_at = #{finishedAt},
    update_time = #{finishedAt}
WHERE id = #{id}
  AND task_type = #{taskType}
  AND status = 'PROCESSING'

UPDATE mt_async_task
SET status = 'DEAD',
    retry_count = #{retryCount},
    finished_at = #{finishedAt},
    last_error = #{lastError},
    update_time = #{finishedAt}
WHERE id = #{id}
  AND task_type = #{taskType}
  AND status = 'PROCESSING'

mapper.select:
SELECT 
FROM mt_async_task
WHERE task_type = #{taskType}
  AND status = 'PROCESSING'
  AND claimed_at IS NOT NULL
  AND claimed_at <= #{claimedBefore}
ORDER BY claimed_at ASC, id ASC
LIMIT #{limit}

mapper.delete:
DELETE FROM mt_async_task
WHERE status = #{status}
  AND finished_at IS NOT NULL
  AND finished_at <= #{finishedBefore}
ORDER BY finished_at ASC, id ASC
LIMIT #{limit}
